import type { Operation } from "../../contracts/src/index.js";
/** Technical evidence only. Keep generated bytes even when a provider misses the request. */
export function assessGenerationOutput(
  input: Operation,
  metadata: Record<string, any>,
) {
  if (input.kind !== "generate") return undefined;
  const warnings: { code: string; message: string }[] = [];
  const duration = Number(input.parameters.duration) * 1000;
  if (
    duration > 0 &&
    metadata.kind === "video" &&
    Math.abs(metadata.durationMs - duration) > 800
  )
    warnings.push({
      code: "OUTPUT_DURATION_MISMATCH",
      message:
        "Measured output differs from requested duration by more than 800 ms; inspect before editing",
    });
  const aspect = input.parameters.aspect_ratio;
  const parts =
    typeof aspect === "string" && /^\d+:\d+$/.test(aspect)
      ? aspect.split(":").map(Number)
      : undefined;
  const requested = parts
    ? parts[0] / parts[1]
    : input.target
      ? input.target.width / input.target.height
      : undefined;
  const measured = metadata.width / metadata.height;
  if (
    requested &&
    Number.isFinite(measured) &&
    Math.abs(measured / requested - 1) > 0.03
  )
    warnings.push({
      code: "OUTPUT_ASPECT_MISMATCH",
      message:
        "Measured output aspect ratio differs from the request; inspect framing before delivery",
    });
  if (
    input.target?.minDurationMs &&
    metadata.durationMs < input.target.minDurationMs
  )
    warnings.push({
      code: "OUTPUT_TOO_SHORT",
      message: "Generated output is shorter than the required action duration",
    });
  return {
    status: "unreviewed",
    requestedParameters: input.parameters,
    target: input.target,
    measured: {
      width: metadata.width,
      height: metadata.height,
      durationMs: metadata.durationMs,
    },
    warnings,
  };
}
